{
  id:"co-prevocational", title:"Pre-vocational evaluation and vocational training", subject:"Rehabilitation", region:"General", stages:"steps",
  aliases:["pre-vocational evaluation","vocational rehabilitation","work evaluation","work hardening","job placement","sheltered workshop","return to work"],
  simple:"Vocational rehabilitation helps a disabled person get back to work or find a new job. First, the team checks what the person can physically and mentally do, and what jobs suit them. Then they train skills, build work tolerance, adapt the workplace and help with placement. Having a job gives income, dignity and a place in society.",
  flow:["Refer patient with work goal","Pre-vocational evaluation: physical, mental, social, interests","Match abilities to job demands (job analysis)","Vocational training, work hardening, adaptations","Placement: open, supported, sheltered or self-employment","Follow-up and job retention support"],
  exam:[
    {h:"Definition and aims", p:["Vocational rehabilitation: the part of rehabilitation that enables disabled persons to secure, retain and advance in suitable employment (ILO).","Pre-vocational evaluation: systematic assessment of a person's physical, mental, emotional, educational and social capacity and interests for work, before vocational training.","Aims: identify realistic job goals, build work readiness, achieve placement and economic independence."]},
    {h:"Components of pre-vocational evaluation", p:["Medical and physical: diagnosis, prognosis, strength, ROM, endurance, hand function, sitting and standing tolerance, mobility, lifting capacity (functional capacity evaluation).","Psychological: intelligence, aptitude, interests, personality, motivation, attention, memory.","Educational and work history; social and family situation; transport and finance.","Work samples and situational assessment: simulated tasks (e.g. VALPAR samples, assembly, typing) to observe speed, accuracy, work habits and behaviour."]},
    {h:"Job analysis and matching", p:["Analyse physical demands (lifting, carrying, standing, fine hand use), environment and skills of the job.","Match with person's capacity; identify modifications (tools, seating, timing, accessibility)."]},
    {h:"Vocational training and placement", p:["Work hardening and work conditioning: graded, simulated job tasks progressing in time and load, body mechanics training.","Skill training in vocational training centres and ITIs, computer and tailoring courses.","Placement types: open (competitive) employment, selective placement, supported employment with job coach, sheltered workshop, home-based work, self-employment (loans).","Indian support: Vocational Rehabilitation Centres for Handicapped (VRCs) under the Ministry of Labour; reservation of jobs (4 percent in government posts) under the RPwD Act 2016; NHFDC loans."]},
    {h:"Role of physiotherapist", p:["Functional capacity evaluation and work tolerance testing.","Graded strengthening, endurance and work simulation; ergonomic advice and injury prevention.","Workplace assessment and recommending modifications or assistive devices."]},
    {h:"Conclusion", p:["Pre-vocational evaluation identifies what the person can do and wants to do; vocational training and placement turn this into sustained, dignified employment."]}
  ],
  tip:"Draw a flow chart: referral, pre-vocational evaluation (medical, psychological, work samples), job analysis and matching, training and work hardening, placement types, follow-up.",
  evidence:[["Supported employment (IPS) for severe mental illness","More people in competitive jobs than traditional vocational rehab","High"],["Workplace-based interventions for musculoskeletal disorders","Reduce sick leave","Moderate"],["Work hardening programmes","May reduce time off work for back pain","Low to moderate"]],
  evidenceSource:"Cochrane reviews of supported employment and workplace interventions",
  outcomes:[["Functional capacity evaluation","Physical work ability"],["Return-to-work rate","Vocational outcome"],["Work samples (e.g. VALPAR)","Work skills and speed"],["Job retention at 6-12 months","Sustained employment"]],
  recent:["The Rights of Persons with Disabilities Act 2016 raised government job reservation to 4 percent for persons with benchmark disabilities."],
  mnemonic:{word:"EMTP", items:[["E","Evaluate"],["M","Match job"],["T","Train and harden"],["P","Place and follow up"]], extra:"Sheltered, supported, open, self-employment."},
  example:"A 34-year-old mason in Dindigul with a below-knee amputation cannot climb scaffolds. After pre-vocational evaluation he trains in a VRC as a tile-cutting supervisor, and his physiotherapist works on standing tolerance and safe lifting.",
  flags:["Unrealistic job goal ignoring medical limits","Return to heavy work without graded conditioning","Workplace discrimination","Loss of disability benefits discouraging work"],
  viva:[["What is a sheltered workshop?","A protected work setting for people who cannot yet manage open employment."],["Name an Indian vocational rehab facility.","Vocational Rehabilitation Centre for Handicapped (VRC) under the Ministry of Labour."],["What is work hardening?","Graded, job-simulated physical conditioning to prepare for return to work."]],
  refs:[{c:"Frontera WR (ed). DeLisa's Physical Medicine and Rehabilitation. Chapter: Vocational rehabilitation."},{c:"Government of India. The Rights of Persons with Disabilities Act, 2016."},{b:"park",ch:"Rehabilitation and disability"}],
  keywords:"pre-vocational evaluation vocational rehabilitation work hardening job placement sheltered workshop VRC",
  mcq:[["Simulated job tasks used to observe work habits are called:",["Goniometry","Work samples","MMT","Gait analysis"],1,"Work samples simulate job tasks for evaluation."],["Employment with an on-site job coach is called:",["Sheltered employment","Supported employment","Open employment without support","Self-employment"],1,"Supported employment provides job coach help in a regular job."]]
}
